// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title MultiSigVault
 * @notice A multi-signature vault requiring threshold confirmations for withdrawals
 * @dev Uses optimistic confirmation with time-locked execution
 */
contract MultiSigVault {
    struct Transaction {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint256 confirmations;
        uint256 submitTime;
    }

    struct SignerProfile {
        bool isActive;
        uint8 weight; // 1-3, higher weight = more trusted
        uint256 nonce;
        bytes32 commitHash; // for commit-reveal confirmation scheme
    }

    address public owner;
    uint256 public threshold;
    uint256 public timeLockDuration;
    uint256 public txCount;

    mapping(address => SignerProfile) public signers;
    mapping(uint256 => Transaction) public transactions;
    mapping(uint256 => mapping(address => bool)) public confirmations;

    address[] public signerList;

    // Commit-reveal to prevent front-running of confirmations
    mapping(bytes32 => bool) public usedCommits;
    mapping(bytes32 => uint256) public commitTimestamps;

    uint256 constant COMMIT_DELAY = 1 minutes;
    uint256 constant COMMIT_EXPIRY = 1 hours;

    event TransactionSubmitted(uint256 indexed txId, address indexed to, uint256 value);
    event TransactionConfirmed(uint256 indexed txId, address indexed signer);
    event TransactionExecuted(uint256 indexed txId);
    event SignerAdded(address indexed signer, uint8 weight);
    event SignerRemoved(address indexed signer);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlySigner() {
        require(signers[msg.sender].isActive, "Not active signer");
        _;
    }

    modifier txExists(uint256 _txId) {
        require(_txId < txCount, "Tx does not exist");
        _;
    }

    modifier notExecuted(uint256 _txId) {
        require(!transactions[_txId].executed, "Already executed");
        _;
    }

    constructor(address[] memory _signers, uint8[] memory _weights, uint256 _threshold) {
        require(_signers.length >= 3, "Need at least 3 signers");
        require(_signers.length == _weights.length, "Length mismatch");
        require(_threshold >= 2, "Threshold too low");

        owner = msg.sender;
        threshold = _threshold;
        timeLockDuration = 1 hours;

        for (uint256 i = 0; i < _signers.length; i++) {
            require(_signers[i] != address(0), "Invalid signer");
            require(!signers[_signers[i]].isActive, "Duplicate signer");
            require(_weights[i] >= 1 && _weights[i] <= 3, "Invalid weight");

            signers[_signers[i]] = SignerProfile({
                isActive: true,
                weight: _weights[i],
                nonce: 0,
                commitHash: bytes32(0)
            });
            signerList.push(_signers[i]);
        }
    }

    receive() external payable {}

    function submitTransaction(address _to, uint256 _value, bytes calldata _data) 
        external onlySigner returns (uint256) 
    {
        uint256 txId = txCount++;
        transactions[txId] = Transaction({
            to: _to,
            value: _value,
            data: _data,
            executed: false,
            confirmations: 0,
            submitTime: block.timestamp
        });

        emit TransactionSubmitted(txId, _to, _value);
        return txId;
    }

    /**
     * @notice Phase 1 of commit-reveal: submit commitment hash
     * @dev Commitment = keccak256(abi.encode(txId, signer, nonce, secret))
     */
    function commitConfirmation(bytes32 _commitment) external onlySigner {
        require(!usedCommits[_commitment], "Commitment already used");
        commitTimestamps[_commitment] = block.timestamp;
    }

    /**
     * @notice Phase 2: reveal and confirm transaction
     * @dev Verifies the commitment matches the reveal parameters
     */
    function revealAndConfirm(
        uint256 _txId, 
        bytes32 _secret
    ) external onlySigner txExists(_txId) notExecuted(_txId) {
        require(!confirmations[_txId][msg.sender], "Already confirmed");

        SignerProfile storage profile = signers[msg.sender];

        // Reconstruct commitment from reveal parameters
        bytes32 commitment = _computeCommitment(_txId, msg.sender, profile.nonce, _secret);

        // Verify commitment was submitted and timing is valid
        uint256 commitTime = commitTimestamps[commitment];
        require(commitTime > 0, "No commitment found");
        require(block.timestamp >= commitTime + COMMIT_DELAY, "Too early to reveal");
        require(block.timestamp <= commitTime + COMMIT_EXPIRY, "Commitment expired");

        // Mark as used and confirm
        usedCommits[commitment] = true;
        confirmations[_txId][msg.sender] = true;
        transactions[_txId].confirmations += profile.weight;
        profile.nonce++;

        emit TransactionConfirmed(_txId, msg.sender);
    }

    /**
     * @dev Compute commitment hash for commit-reveal scheme
     * @notice Uses abi.encode for unambiguous encoding of parameters
     */
    function _computeCommitment(
        uint256 _txId,
        address _signer, 
        uint256 _nonce,
        bytes32 _secret
    ) internal pure returns (bytes32) {
        return keccak256(abi.encode(_txId, _signer, _nonce, _secret));
    }

    function executeTransaction(uint256 _txId) 
        external onlySigner txExists(_txId) notExecuted(_txId) 
    {
        Transaction storage txn = transactions[_txId];
        require(txn.confirmations >= threshold, "Below threshold");
        require(block.timestamp >= txn.submitTime + timeLockDuration, "Time lock active");

        txn.executed = true;

        (bool success, ) = txn.to.call{value: txn.value}(txn.data);
        require(success, "Execution failed");

        emit TransactionExecuted(_txId);
    }

    function addSigner(address _signer, uint8 _weight) external onlyOwner {
        require(_signer != address(0), "Invalid address");
        require(!signers[_signer].isActive, "Already a signer");
        require(_weight >= 1 && _weight <= 3, "Invalid weight");

        signers[_signer] = SignerProfile({
            isActive: true,
            weight: _weight,
            nonce: 0,
            commitHash: bytes32(0)
        });
        signerList.push(_signer);

        emit SignerAdded(_signer, _weight);
    }

    function removeSigner(address _signer) external onlyOwner {
        require(signers[_signer].isActive, "Not active");
        signers[_signer].isActive = false;
        emit SignerRemoved(_signer);
    }

    function getSignerCount() external view returns (uint256 count) {
        for (uint256 i = 0; i < signerList.length; i++) {
            if (signers[signerList[i]].isActive) count++;
        }
    }

    function isConfirmed(uint256 _txId) external view returns (bool) {
        return transactions[_txId].confirmations >= threshold;
    }
}
